  private fireShot(playerId: string, direction: Vec3, normalizedPower: number): void {
    if (!this.ball) return;
    const power = clamp(normalizedPower, 0.01, 1);
    const result = this.ball.applyShot(direction, chargeForPower(power));
    if (!result.accepted) return;
    this.sequence += 1;
    const command: ShotCommand = {
      playerId,
      holeId: this.hole.id,
      direction: { x: direction.x, y: 0, z: direction.z },
      normalizedPower: power,
      clientSequence: this.sequence,
      issuedAt: Date.now(),
    };
    this.match = this.matchManager.markShotSubmitted(this.match);
    this.match = this.matchManager.applySimulationEvent(this.match, this.course, { type: 'shot-accepted', command });
    this.shotClock = 0;
    this.settleClock = 0;
    this.aimPower = 0;
    this.statusText = undefined;
    this.aimArrow.visible = false;
  }

  private finishTurn(playerId: string, position: Vec3): void {
    this.playerPositions.set(playerId, { ...position });
    this.holeSystem.markSafePosition(playerId, position);
    const score = this.scoreOf(playerId);
    if (score && !score.completed && score.strokes >= this.match.settings.strokeLimitPerHole) {
      this.match = this.matchManager.enforceStrokeLimit(this.match, this.course, playerId);
      this.toast('STROKE LIMIT · ' + this.nameOf(playerId).toUpperCase());
    } else {
      this.match = this.matchManager.applySimulationEvent(this.match, this.course, {
        type: 'ball-stopped',
        playerId,
        position: { ...position },
      });
    }
    this.afterMatchUpdate();
  }

  private completeHole(playerId: string): void {
    const strokes = this.scoreOf(playerId)?.strokes ?? 0;
    this.playerPositions.set(playerId, { ...this.hole.cup.position });
    this.match = this.matchManager.applySimulationEvent(this.match, this.course, {
      type: 'ball-holed',
      playerId,
      holeId: this.hole.id,
      strokes,
    });
    this.toast(this.nameOf(playerId).toUpperCase() + ' · ' + this.scoreManager.parLabel(strokes, this.hole.par));
    this.afterMatchUpdate();
  }

  private resetBall(playerId: string, hazard: ReturnType<HoleRuntime['hazardAt']>): void {
    if (!this.ball) return;
    const resolution = this.holeSystem.resolveHazard(playerId, this.hole, hazard);
    this.ball.reset(resolution.resetPosition);
    this.match = this.matchManager.applySimulationEvent(this.match, this.course, {
      type: 'ball-reset',
      playerId,
      position: resolution.resetPosition,
      penaltyStrokes: resolution.penaltyStrokes,
    });
    this.toast((hazard ? 'HAZARD' : 'OUT OF BOUNDS') + ' · +' + String(resolution.penaltyStrokes));
    this.finishTurn(playerId, resolution.resetPosition);
  }

  private afterMatchUpdate(): void {
    if (this.match.phase === 'match-results') {
      this.showResults();
      return;
    }
    if (this.match.currentHoleIndex !== this.holeIndex) {
      this.loadHole(this.match.currentHoleIndex);
      return;
    }
    this.syncTurn();
  }

  private syncTurn(): void {
    const playerId = this.match.activePlayerId;
    if (!playerId || this.match.phase !== 'aiming') return;
    this.turnPlayerId = playerId;
    const position = this.playerPositions.get(playerId) ?? this.hole.spawn;
    this.ball?.reset(position);
    this.holeSystem.markSafePosition(playerId, position);
    this.aim.cancel();
    this.aimPower = 0;
    this.shotClock = 0;
    this.settleClock = 0;
    this.focusCamera(position);

    const bot = this.botProfiles.get(playerId);
    if (!bot) {
      this.botScheduler.reset();
      this.botPlan = undefined;
      this.statusText = undefined;
      return;
    }
    this.botScheduler.begin(bot.displayName, bot.personality);
    this.botPlan = planShot(bot, {
      playerId,
      hole: this.hole,
      ballPosition: position,
      clientSequence: this.sequence + 1,
      issuedAt: Date.now(),
      seed: playerId + ':' + this.hole.id + ':' + String(this.sequence),
    });
  }

  /** Arcade rolling model: constant deceleration while the ball hugs the surface. */
  private applyRollingResistance(dt: number): void {
    const ball = this.ball;
    if (!ball) return;
    const velocity = ball.velocity;
    if (Math.abs(velocity.y) > AIRBORNE_SPEED) return;
    const horizontal = Math.hypot(velocity.x, velocity.z);
    if (horizontal <= 1e-4) return;
    const deceleration = this.runtime?.decelerationAt(ball.position) ?? 3.4;
    const factor = Math.max(0, horizontal - deceleration * dt) / horizontal;
    ball.body.setLinvel({ x: velocity.x * factor, y: velocity.y, z: velocity.z * factor }, true);
  }

  private updateCamera(dt: number): void {
    if (this.match.phase === 'simulating' || this.match.phase === 'hole-intro') {
      const focus = this.ballPosition();
      this.cameraController.setTarget({ x: focus.x, y: focus.y + 0.35, z: focus.z });
    }
    this.cameraController.update(dt, this.cameraView());
    if (this.options.input.wasPressed('camera-reset')) this.focusCamera(this.ballPosition());
    const pose = this.cameraController.state;
    const camera = this.options.camera;
    camera.position.set(pose.position.x, pose.position.y, pose.position.z);
    camera.lookAt(pose.target.x, pose.target.y, pose.target.z);
  }

  private focusCamera(position: Vec3): void {
    const dx = this.hole.cup.position.x - position.x;
    const dz = this.hole.cup.position.z - position.z;
    const yaw = Math.abs(dx) + Math.abs(dz) < 1e-5 ? Math.PI : Math.atan2(-dx, -dz);
    this.cameraController.reset({ x: position.x, y: position.y + 0.35, z: position.z });
    this.cameraController.setOrbit(yaw, CAMERA_PITCH, CAMERA_DISTANCE);
  }

  private syncMeshes(): void {
    const ball = this.ball;
    for (const [playerId, mesh] of this.ballMeshes) {
      const live = ball !== undefined && playerId === this.turnPlayerId;
      const position = live && ball ? ball.position : this.playerPositions.get(playerId);
      if (position) mesh.position.set(position.x, position.y, position.z);
      if (live && ball) {
        const rotation = ball.body.rotation();
        mesh.quaternion.set(rotation.x, rotation.y, rotation.z, rotation.w);
      }
      mesh.visible = this.scoreOf(playerId)?.completed !== true;
    }
  }

  private updatePresentation(dt: number): void {
    const input = this.options.input;
    this.minimapClock += dt;
    if (this.minimapClock >= MINIMAP_INTERVAL) {
      this.minimapClock = 0;
      this.minimap.render(buildMinimapModel(this.hole, this.ballPosition()));
    }
    if (this.toastClock > 0) {
      this.toastClock -= dt;
      if (this.toastClock <= 0) this.toastElement.hidden = true;
    }

    this.hud.render({
      holeNumber: this.holeIndex + 1,
      holeCount: this.course.holes.length,
      holeName: this.hole.name,
      par: this.hole.par,
      strokes: this.scoreOf(this.turnPlayerId ?? '')?.strokes ?? 0,
      power: this.aimPower,
      canShoot: this.isHumanTurn() && this.match.phase === 'aiming' && (this.ball?.canShoot ?? false),
      statusText: this.statusLine(),
    });
    this.hint.hidden = this.paused || !this.results.element.hidden;

    const showScoreboard =
      this.results.element.hidden && (input.isDown('scoreboard') || this.introClock < 0 || this.paused);
    this.scoreboard.element.hidden = !showScoreboard;
    if (showScoreboard) {
      this.scoreboard.render({
        players: this.uiPlayers(),
        holeNumber: this.holeIndex + 1,
        holeCount: this.course.holes.length,
      });
    }
  }
